import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Démarrer","description":"","frontmatter":{"title":"Démarrer"},"headers":[],"relativePath":"agent/demarrer.md","filePath":"agent/demarrer.md"}'),n={name:"agent/demarrer.md"};function d(i,e,s,u,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="demarrer" tabindex="-1">Démarrer <a class="header-anchor" href="#demarrer" aria-label="Permalink to &quot;Démarrer&quot;">​</a></h1><p>Avant une première tâche, demandez à l&#39;agent de vérifier que tout est en place. Un seul appel suffit.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Vérifie que Daimon est prêt. »</p></blockquote><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><p>Il appelle <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>, sans paramètre. L&#39;outil sonde les autorisations avec des API qui n&#39;ouvrent jamais de boîte de dialogue, puis rend l&#39;état de chaque organe. Il peut aussi appeler <a href="/Daimon/reference/diagnostic.html#ping"><code>ping</code></a>, qui répond <code>pong</code> et prouve seulement que le serveur répond.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Un compte rendu lisible dans la conversation. Les clés que l&#39;agent lit :</p><table tabindex="0"><thead><tr><th>Clé</th><th>Ce qu&#39;elle dit</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Le verdict global</td></tr><tr><td><code>permissions</code></td><td>Enregistrement de l&#39;écran et Accessibilité : accordés ou non</td></tr><tr><td><code>organs</code></td><td>L&#39;état de Vue, Touché et Mains, et ce qui le fonde</td></tr><tr><td><code>ceiling</code></td><td>Le plafond actif</td></tr><tr><td><code>consequences</code></td><td>Ce que chaque autorisation manquante change concrètement pour chaque outil</td></tr><tr><td><code>next</code></td><td>Les prochaines étapes suggérées</td></tr></tbody></table><h2 id="si-quelque-chose-manque" tabindex="-1">Si quelque chose manque <a class="header-anchor" href="#si-quelque-chose-manque" aria-label="Permalink to &quot;Si quelque chose manque&quot;">​</a></h2><ul><li><strong>Une autorisation manque</strong> : <code>consequences</code> dit quels outils sont touchés. Accordez-la dans les réglages du système : <a href="/Daimon/guide/autorisations.html">Autorisations</a>.</li><li><strong>L&#39;agent ne voit aucun outil Daimon</strong> : Daimon n&#39;est pas enregistré dans cet agent, ou l&#39;agent n&#39;a pas été redémarré. Voir <a href="/Daimon/guide/clients-mcp.html">Clients IA</a>.</li><li><strong>Le plafond est à L0</strong> : c&#39;est le réglage par défaut. L&#39;agent regardera, mais n&#39;agira pas : voir <a href="/Daimon/agent/agir.html">Agir</a>.</li></ul><p>Suite : <a href="/Daimon/agent/regarder.html">Regarder l&#39;écran</a>.</p>',12)])])}const q=a(n,[["render",d]]);export{h as __pageData,q as default};
